const SAVE={bullying:"progressoBullying",inclusao:"progressoInclusao"},RANK="rankingJuntos",screen=document.getElementById("screen"),sound=document.getElementById("sound");let muted=localStorage.getItem("sonsJuntos")==="off",S={};
function esc(x){return String(x).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function beep(t){if(muted)return;try{let C=AudioContext||webkitAudioContext,c=new C(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=t==="ok"?660:t==="bad"?180:t==="phase"?880:430;g.gain.value=.04;o.start();o.stop(c.currentTime+(t==="phase"?.22:.1))}catch(e){}}
function save(){localStorage.setItem(SAVE[S.game],JSON.stringify(S))}
function get(g){try{return JSON.parse(localStorage.getItem(SAVE[g]))}catch(e){return null}}
function points(n){return n<=30?10:n<=60?12:n<=90?15:n<=120?20:25}
function diff(n){return n<=10?"🟢 Iniciante":n<=20?"🟢 Iniciante +":n<=30?"🟢 Básico":n<=40?"🟡 Básico +":n<=50?"🟡 Intermediário":n<=60?"🟡 Intermediário +":n<=75?"🟠 Médio":n<=90?"🟠 Médio +":n<=105?"🟠 Difícil":n<=120?"🔴 Difícil +":n<=130?"🔴 Avançado":n<=140?"🔴 Avançado +":n<=145?"🟣 Muito difícil":n<=149?"🟣 Expert":"🟣 Desafio máximo"}
function explanation(t){return({bullying:"Bullying pode envolver agressões repetidas e sofrimento. Procurar apoio e interromper a violência com segurança é importante.",cyberbullying:"No ambiente digital, não compartilhar humilhações e buscar ajuda reduz a circulação do dano.",empatia:"Empatia é considerar sentimentos e necessidades de outras pessoas antes de agir.",exclusão:"Inclusão exige oportunidade real de participação, sem barreiras injustas.",preconceito:"Respeitar diferenças significa evitar julgamentos baseados em estereótipos.",testemunha:"Uma testemunha pode apoiar quem sofreu a agressão e procurar ajuda segura.",respeito:"Discordar é possível sem humilhar, ameaçar ou desrespeitar.",escola:"Problemas repetidos de convivência devem ser comunicados a pessoas responsáveis.",deficiência:"Uma pessoa deve ser valorizada por suas capacidades e escolhas, não reduzida à deficiência.",acessibilidade:"Um recurso acessível precisa estar disponível e utilizável na prática.",capacitismo:"Capacitismo ocorre quando a deficiência é usada para inferiorizar, limitar ou presumir incapacidade.",autismo:"Adaptações podem reduzir barreiras e favorecer participação sem exigir que todos ajam do mesmo modo.",idosos:"A idade não determina a capacidade de uma pessoa; evitar estereótipos também é respeito.",cadeira_de_rodas:"Espaços de circulação precisam permanecer livres para garantir acessibilidade.",linguagem:"Uma linguagem respeitosa evita expressões que inferiorizam ou definem alguém apenas por uma característica.",equidade:"Equidade considera necessidades diferentes para criar oportunidades reais de participação.",diversidade:"Diversidade envolve reconhecer diferenças e construir convivência respeitosa.",inclusão:"Inclusão significa remover barreiras e garantir participação significativa."}[t]||"A melhor atitude preserva dignidade, segurança, respeito e participação.")}
function home(){let a=get("bullying"),b=get("inclusao");screen.innerHTML=`<div class="wrap"><section class="hero"><div style="font-size:3rem">🤝💙</div><h1>Juntos Contra o Bullying</h1><p>Jogo educativo para reconhecer bullying, cyberbullying, exclusão, preconceito, capacitismo e atitudes que fortalecem empatia, respeito e inclusão.</p><div class="actions"><button class="primary" onclick="choose()">▶ Iniciar jogo</button><button class="secondary" onclick="ranking()">🏆 Ranking</button></div></section><section class="games"><article class="card game-card"><h2>🛡️ A Luta Contra o Bullying</h2><p>150 perguntas • 15 fases</p>${a?`<p>Progresso: pergunta ${Math.min(a.index+1,150)}/150 • ${a.score} pontos</p><button class="primary" onclick="resume('bullying')">▶ Continuar</button> <button class="danger" onclick="erase('bullying')">Apagar progresso</button>`:`<button class="primary" onclick="start('bullying')">Começar</button>`}</article><article class="card game-card"><h2>♿ Respeito às Diferenças</h2><p>150 perguntas • 15 fases</p>${b?`<p>Progresso: pergunta ${Math.min(b.index+1,150)}/150 • ${b.score} pontos</p><button class="primary" onclick="resume('inclusao')">▶ Continuar</button> <button class="danger" onclick="erase('inclusao')">Apagar progresso</button>`:`<button class="primary" onclick="start('inclusao')">Começar</button>`}</article></section><section class="card game-card" style="margin-top:18px"><h3>🔊 Sons</h3><button class="secondary" onclick="toggleSound()">${muted?"🔇 Sons desativados":"🔊 Sons ativados"}</button><h3>👥 Criadores</h3><p>Adalberto Alves • Eloá Dama • Noelly Veloso</p></section></div>`}
function toggleSound(){muted=!muted;localStorage.setItem("sonsJuntos",muted?"off":"on");beep("click");home()}sound.onclick=toggleSound;
function choose(){screen.innerHTML=`<div class="wrap"><section class="card hero"><h1>Escolha um jogo</h1><div class="actions"><button class="primary" onclick="start('bullying')">🛡️ A Luta Contra o Bullying</button><button class="primary" onclick="start('inclusao')">♿ Respeito às Diferenças</button><button class="secondary" onclick="home()">Voltar</button></div></section></div>`}
function start(g){S={game:g,index:0,score:0,answered:false,selected:null,order:[],correctCount:0};render();beep("click")}
function resume(g){let x=get(g);if(x){S=x;render()}}
function erase(g){if(confirm("Apagar somente o progresso deste jogo?")){localStorage.removeItem(SAVE[g]);home()}}
function render(){let q=QUESTIONS[S.game][S.index];if(!q){finish();return}if(!S.order.length){S.order=[0,1,2,3].sort(()=>Math.random()-.5);save()}let n=S.index+1,p=Math.floor(S.index/10)+1;screen.innerHTML=`<div class="wrap"><div class="stats"><span class="stat">Fase ${p} de 15</span><span class="stat">Pergunta ${n} de 150</span><span class="stat">Nível ${n}/150</span><span class="stat">${diff(n)}</span><span class="stat">Pontos: ${S.score}</span></div><div class="progress"><i style="width:${n/150*100}%"></i></div><section class="card question"><p><b>Tema:</b> ${esc(q.tema)}</p><h2>${esc(q.pergunta)}</h2><div class="answers">${S.order.map((orig,pos)=>`<button class="answer ${S.answered?(orig===q.correta?"correct":orig===S.selected?"wrong":""):""}" ${S.answered?"disabled":""} onclick="answer(${orig})"><b>${"ABCD"[pos]})</b> ${esc(q.alternativas[orig])}</button>`).join("")}</div>${S.answered?`<div class="feedback ${S.selected===q.correta?"good":"bad"}"><b>${S.selected===q.correta?"✅ CORRETA":"❌ INCORRETA"}</b><p>${S.selected===q.correta?"Muito bem! Você escolheu uma atitude de respeito.":`A alternativa correta era <b>${"ABCD"[S.order.indexOf(q.correta)]})</b> ${esc(q.alternativas[q.correta])}.`}</p><p>${explanation(q.tema)}</p></div><div class="actions"><button class="primary" onclick="next()">Próxima pergunta</button></div>`:""}</section></div>`}
function answer(i){if(S.answered)return;let q=QUESTIONS[S.game][S.index];S.selected=i;S.answered=true;if(i===q.correta){S.score+=points(q.nivel);S.correctCount++;beep("ok")}else beep("bad");save();render()}
function next(){let old=Math.floor(S.index/10),ni=S.index+1;if(ni>=150){S.index=150;save();finish();return}S.index=ni;S.answered=false;S.selected=null;S.order=[];save();if(Math.floor(ni/10)>old){beep("phase");screen.innerHTML=`<div class="wrap"><section class="card phase"><div style="font-size:4rem">🎉</div><h1>Fase concluída!</h1><p>Você terminou a Fase ${old+1}.</p><p>Prepare-se para um novo desafio!</p><button class="primary" onclick="render()">Continuar</button></section></div>`}else render()}
function finish(){let pct=Math.round(S.correctCount/150*100),medal=pct>=90?"🥇 Ouro":pct>=70?"🥈 Prata":pct>=50?"🥉 Bronze":"🏅 Participação";localStorage.removeItem(SAVE[S.game]);beep("phase");screen.innerHTML=`<div class="wrap"><section class="card phase"><div class="medal">${medal[0]}</div><h1>🎉 Jogo concluído!</h1><h2>${S.score} pontos</h2><p>Acertos: <b>${S.correctCount}/150</b></p><p>Percentual: <b>${pct}%</b></p><p>Medalha: <b>${medal}</b></p><div class="actions"><button class="primary" onclick="askName('${S.game}',${S.score},${pct},'${medal}')">Salvar no ranking</button><button class="secondary" onclick="start('${S.game}')">Jogar novamente</button><button class="secondary" onclick="home()">Menu</button><button class="secondary" onclick="ranking()">Ranking</button></div></section></div>`}
function askName(g,s,p,m){screen.insertAdjacentHTML("beforeend",`<div class="modal"><div class="card"><h2>🏆 Salvar resultado</h2><input id="name" maxlength="30" placeholder="Seu nome"><div class="actions"><button class="primary" onclick="saveRank('${g}',${s},${p},'${m}')">Salvar</button><button class="secondary" onclick="this.closest('.modal').remove()">Cancelar</button></div></div></div>`)}
function saveRank(g,s,p,m){let r=[];try{r=JSON.parse(localStorage.getItem(RANK))||[]}catch(e){}let name=(document.getElementById("name").value||"Jogador").trim().slice(0,30);r.push({name,game:g,score:s,pct:p,medal:m});r.sort((a,b)=>b.score-a.score);localStorage.setItem(RANK,JSON.stringify(r.slice(0,100)));ranking()}
function ranking(){let r=[];try{r=JSON.parse(localStorage.getItem(RANK))||[]}catch(e){}screen.innerHTML=`<div class="wrap"><section class="card game-card"><h1>🏆 Ranking</h1>${r.length?`<div style="overflow:auto"><table class="table"><tr><th>#</th><th>Nome</th><th>Jogo</th><th>Pontos</th><th>%</th><th>Medalha</th></tr>${r.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.name)}</td><td>${x.game==="bullying"?"A Luta Contra o Bullying":"Respeito às Diferenças"}</td><td>${x.score}</td><td>${x.pct}%</td><td>${esc(x.medal)}</td></tr>`).join("")}</table></div>`:"<p>Ainda não há resultados salvos.</p>"}<div class="actions" style="margin-top:20px"><button class="secondary" onclick="home()">Voltar</button>${r.length?`<button class="danger" onclick="localStorage.removeItem('${RANK}');ranking()">Limpar ranking</button>`:""}</div></section></div>`}
home();